struct saveInfo
{
    char data[96];
    int valid;
    char tail[4];
};

struct Career
{
    char data[0x10A48];
    void init();
};

struct GlobalDataClass
{
    void init();
};

class GenericGameSaver
{
    static GenericGameSaver *instance;
public:
    static GenericGameSaver *inst() { return instance; }
    void setFileInfo(saveInfo info);
    void readFile(int port, int slot, void *data, int size,
                  void (*callback)(void *, int), void *userData);
};

class MCDetectFrontEnd
{
public:
    bool findMostRecentGame(int &port, int &slot, saveInfo &newest);
    bool findGlobalData(int &port, int &slot);
    void goState(int which);
    static void configLoadCallback(void *userData, int percent);
    int loadMostRecentGame();
};

extern Career *g_career;
extern GlobalDataClass globalCareerData;
extern saveInfo currentGame;
extern int savePort, saveSlot;
extern bool foundGame;
extern "C" void *memcpy(void *, const void *, unsigned int);

enum {
    GSOk = 0,
    GSErrorOther = -2,
    INVALID_CARD_VALUE = -1,
    MC_LOADING = 3,
    MC_DONE = 4,
    MC_EXIT = 9,
    MC_LOAD_GLOBAL = 10
};

__asm__(".equ _16GenericGameSaver$instance, 0x0041E5B8");
__asm__(".equ g_career, 0x00427C9C");
__asm__(".equ globalCareerData, 0x004349B8");
__asm__(".equ currentGame, 0x0042EB50");
__asm__(".equ savePort, 0x0041E5AC");
__asm__(".equ saveSlot, 0x0041E5B0");
__asm__(".equ foundGame, 0x003FCE00");
__asm__(".equ init__6Career, 0x0025A4C0");
__asm__(".equ init__15GlobalDataClass, 0x002EFC10");
__asm__(".equ findMostRecentGame__16MCDetectFrontEndRiT1R8saveInfo, 0x001A4618");
__asm__(".equ findGlobalData__16MCDetectFrontEndRiT1, 0x001A47B8");
__asm__(".equ goState__16MCDetectFrontEndi, 0x001A3930");
__asm__(".equ setFileInfo__16GenericGameSaverG8saveInfo, 0x001E6030");
__asm__(".equ readFile__16GenericGameSaveriiPviPFPvi_vT3, 0x001E4A88");
__asm__(".equ configLoadCallback__16MCDetectFrontEndPvi, 0x001A4518");

int MCDetectFrontEnd::loadMostRecentGame()
{
	saveInfo  mostRecent;
	mostRecent.valid = -1;

	findMostRecentGame(savePort, saveSlot, mostRecent);

	// Now that we're done, check how many valid cards
	if (mostRecent.valid != GSOk)
	{
		g_career->init();
		globalCareerData.init();
		if (findGlobalData(savePort, saveSlot))
			goState(MC_LOAD_GLOBAL);
		else if (savePort != INVALID_CARD_VALUE)
			goState(MC_DONE);
		else
			goState(MC_EXIT);
		return GSOk;
	}
	else 
	{
		foundGame = true; 
		memcpy(&currentGame, &mostRecent, sizeof(saveInfo));
		GenericGameSaver::inst()->setFileInfo(mostRecent);
		goState(MC_LOADING);
		GenericGameSaver::inst()->readFile(savePort,saveSlot,g_career,sizeof(Career), MCDetectFrontEnd::configLoadCallback, this);
		return GSOk;
	}

}
